# Generated by build.py from recipe.yml for recipe https-serve-a-pfx-certificate. Do not edit.
set -e
cd "$(dirname "$0")"
mkdir -p site site2
printf '%s\n' 'hello from surl' > site/hello.txt
printf '%s\n' 'hello from surl' > site2/hello.txt
openssl req -x509 -newkey rsa:2048 -nodes -keyout server.key -out server.pem -days 30 -subj "/CN=127.0.0.1" -addext "subjectAltName=IP:127.0.0.1"
openssl pkcs12 -export -out server.pfx -inkey server.key -in server.pem -passout pass:s3cret
surl --directory site --cert server.pfx --cert-type P12 --pass s3cret https://127.0.0.1:8080/ &
sleep 1
curl -s --cacert server.pem https://127.0.0.1:8080/hello.txt
kill $(jobs -p)
